#!/usr/bin/env python3
"""Offline DNS model-based regression workbench.

Reads one UTF-8 JSON document on stdin, validates it against the frozen
contract, executes the local resolution model for every query/profile pair,
adjudicates the supplied observations and computes an exact minimum-cost
diagnostic basis.  Emits one JSON document on stdout and exits 0.
"""

import ipaddress
import json
import re
import sys

ERROR_JSON = '{"error":"invalid-input"}'

MAX_INPUT_BYTES = 8 * 1024 * 1024
MAX_DEPTH = 32

MAX_ZONES = 16
MAX_ZONE_RECORD_ENTRIES = 1024
MAX_RRSET_DISTINCT = 64
MAX_PROFILES = 8
MIN_PROFILES = 1
MAX_QUERIES = 20
MAX_OBSERVATIONS = 64
MAX_OBSERVED_ANSWER = 128
MAX_ALIASES = 64
MAX_COST = 1000
MAX_TXT_CHARS = 256
MAX_LABEL_LEN = 63
MAX_WIRE_LEN = 255
MAX_ID_LEN = 32

TYPES = ('A', 'AAAA', 'TXT', 'CNAME')
RCODES = ('NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED')
CNAME_MODES = ('follow', 'stop')
WILDCARD_MODES = ('rfc', 'off', 'one-label')

ID_RE = re.compile(r'\A[A-Za-z0-9_-]{1,32}\Z')
LABEL_RE = re.compile(r'\A[A-Za-z0-9_-]{1,63}\Z')
A_RE = re.compile(r'\A(?:0|[1-9][0-9]{0,2})(?:\.(?:0|[1-9][0-9]{0,2})){3}\Z')


class Invalid(Exception):
    """Raised for any contract violation in the input document."""


# --------------------------------------------------------------------------
# small structural helpers
# --------------------------------------------------------------------------

def need(cond):
    if not cond:
        raise Invalid()


def as_dict(value):
    need(isinstance(value, dict))
    return value


def as_list(value):
    need(isinstance(value, list))
    return value


def as_str(value):
    need(isinstance(value, str))
    return value


def as_int(value):
    need(isinstance(value, int) and not isinstance(value, bool))
    return value


def exact_keys(obj, keys):
    need(isinstance(obj, dict))
    need(len(obj) == len(keys))
    for key in keys:
        need(key in obj)
    return obj


def check_id(value):
    text = as_str(value)
    need(len(text) <= MAX_ID_LEN)
    need(ID_RE.match(text) is not None)
    return text


# --------------------------------------------------------------------------
# names and record data
# --------------------------------------------------------------------------

def check_name(value):
    """Validate an absolute ASCII domain name; return its canonical form."""
    text = as_str(value)
    if text == '.':
        return '.'
    need(text.endswith('.'))
    body = text[:-1]
    need(body != '')
    wire = 1
    for label in body.split('.'):
        if label == '*':
            wire += 2
        else:
            need(LABEL_RE.match(label) is not None)
            wire += 1 + len(label)
        need(wire <= MAX_WIRE_LEN)
    return text.lower()


def label_count(name):
    if name == '.':
        return 0
    return name.count('.')


def parent_name(name):
    if name == '.':
        return None
    rest = name[name.index('.') + 1:]
    return rest if rest else '.'


def at_or_below(name, origin):
    """True when `name` is `origin` or a whole-label descendant of it."""
    if origin == '.':
        return True
    if name == origin:
        return True
    return name.endswith('.' + origin)


def wildcard_name(name):
    if name == '.':
        return '*.'
    return '*.' + name


def check_a_data(text):
    need(A_RE.match(text) is not None)
    for octet in text.split('.'):
        need(int(octet) <= 255)
    return text


def check_aaaa_data(text):
    need('%' not in text)
    try:
        return ipaddress.IPv6Address(text).compressed
    except (ValueError, TypeError):
        raise Invalid()


def check_txt_data(text):
    need(len(text) <= MAX_TXT_CHARS)
    for char in text:
        need('\u0020' <= char <= '\u007e')
    return text


def check_data(rtype, value):
    text = as_str(value)
    if rtype == 'A':
        return check_a_data(text)
    if rtype == 'AAAA':
        return check_aaaa_data(text)
    if rtype == 'TXT':
        return check_txt_data(text)
    return check_name(text)


def check_type(value):
    rtype = as_str(value)
    need(rtype in TYPES)
    return rtype


def check_record(value):
    """Validate a record object; return the canonical (owner, type, data)."""
    obj = exact_keys(as_dict(value), ('owner', 'type', 'data'))
    owner = check_name(obj['owner'])
    rtype = check_type(obj['type'])
    data = check_data(rtype, obj['data'])
    return (owner, rtype, data)


# --------------------------------------------------------------------------
# document validation
# --------------------------------------------------------------------------

def reject_float(text):
    raise Invalid()


def reject_constant(text):
    raise Invalid()


def reject_pairs(pairs):
    seen = set()
    out = {}
    for key, value in pairs:
        need(key not in seen)
        seen.add(key)
        out[key] = value
    return out


def container_depth(value):
    """Iterative maximum nesting depth of containers (root container == 1)."""
    best = 0
    stack = [(value, 1)]
    while stack:
        node, depth = stack.pop()
        if depth > best:
            best = depth
            if best > MAX_DEPTH:
                return best
        child = depth + 1
        if isinstance(node, dict):
            for item in node.values():
                stack.append((item, child))
        elif isinstance(node, list):
            for item in node:
                stack.append((item, child))
    return best


def build_zone(obj):
    exact_keys(obj, ('origin', 'records'))
    origin = check_name(obj['origin'])
    raw_records = as_list(obj['records'])
    rrsets = {}
    owner_types = {}
    for raw in raw_records:
        owner, rtype, data = check_record(raw)
        need(at_or_below(owner, origin))
        rrsets.setdefault((owner, rtype), set()).add(data)
        owner_types.setdefault(owner, set()).add(rtype)
    for (owner, rtype), values in rrsets.items():
        need(len(values) <= MAX_RRSET_DISTINCT)
    for owner, types in owner_types.items():
        if 'CNAME' in types:
            need(len(types) == 1)
            need(len(rrsets[(owner, 'CNAME')]) == 1)
            need(owner != origin)
    existing = {origin}
    for owner in owner_types:
        node = owner
        while True:
            if node in existing:
                break
            existing.add(node)
            if node == origin:
                break
            node = parent_name(node)
    by_owner = {}
    for (owner, rtype), values in rrsets.items():
        by_owner.setdefault(owner, {})[rtype] = tuple(sorted(values))
    return {
        'origin': origin,
        'labels': label_count(origin),
        'suffix': None if origin == '.' else '.' + origin,
        'existing': existing,
        'by_owner': by_owner,
        'entries': len(raw_records),
    }


def parse_document(raw_bytes):
    need(len(raw_bytes) <= MAX_INPUT_BYTES)
    try:
        text = raw_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid()
    try:
        doc = json.loads(text, parse_float=reject_float,
                         parse_constant=reject_constant,
                         object_pairs_hook=reject_pairs)
    except RecursionError:
        raise Invalid()
    except Invalid:
        raise
    except Exception:
        raise Invalid()
    need(container_depth(doc) <= MAX_DEPTH)
    root = exact_keys(as_dict(doc), ('zones', 'profiles', 'queries',
                                     'observations'))

    raw_zones = as_list(root['zones'])
    need(len(raw_zones) <= MAX_ZONES)
    zones = []
    origins = set()
    total_entries = 0
    for raw in raw_zones:
        zone = build_zone(as_dict(raw))
        need(zone['origin'] not in origins)
        origins.add(zone['origin'])
        total_entries += zone['entries']
        need(total_entries <= MAX_ZONE_RECORD_ENTRIES)
        zones.append(zone)
    zones.sort(key=lambda z: (-z['labels'], z['origin']))

    raw_profiles = as_list(root['profiles'])
    need(MIN_PROFILES <= len(raw_profiles) <= MAX_PROFILES)
    profiles = []
    profile_ids = set()
    for raw in raw_profiles:
        obj = exact_keys(as_dict(raw), ('id', 'max_aliases', 'cname',
                                        'wildcard'))
        pid = check_id(obj['id'])
        need(pid not in profile_ids)
        profile_ids.add(pid)
        max_aliases = as_int(obj['max_aliases'])
        need(0 <= max_aliases <= MAX_ALIASES)
        cname = as_str(obj['cname'])
        need(cname in CNAME_MODES)
        wildcard = as_str(obj['wildcard'])
        need(wildcard in WILDCARD_MODES)
        profiles.append({'id': pid, 'max_aliases': max_aliases,
                         'cname': cname, 'wildcard': wildcard})

    raw_queries = as_list(root['queries'])
    need(len(raw_queries) <= MAX_QUERIES)
    queries = []
    query_ids = set()
    for raw in raw_queries:
        obj = exact_keys(as_dict(raw), ('id', 'name', 'type', 'cost'))
        qid = check_id(obj['id'])
        need(qid not in query_ids)
        query_ids.add(qid)
        name = check_name(obj['name'])
        qtype = check_type(obj['type'])
        cost = as_int(obj['cost'])
        need(1 <= cost <= MAX_COST)
        queries.append({'id': qid, 'name': name, 'type': qtype, 'cost': cost})

    raw_observations = as_list(root['observations'])
    need(len(raw_observations) <= MAX_OBSERVATIONS)
    observations = []
    observation_ids = set()
    for raw in raw_observations:
        obj = exact_keys(as_dict(raw), ('id', 'query', 'profile', 'result'))
        oid = check_id(obj['id'])
        need(oid not in observation_ids)
        observation_ids.add(oid)
        ref_query = check_id(obj['query'])
        need(ref_query in query_ids)
        ref_profile = check_id(obj['profile'])
        need(ref_profile in profile_ids)
        result = as_dict(obj['result'])
        exact_keys(result, ('status',))
        status = as_str(result['status'])
        if status == 'timeout':
            observations.append({'id': oid, 'query': ref_query,
                                 'profile': ref_profile, 'status': 'timeout',
                                 'rcode': None, 'answer': None})
        elif status == 'response':
            exact_keys(result, ('status', 'rcode', 'answer'))
            rcode = as_str(result['rcode'])
            need(rcode in RCODES)
            raw_answer = as_list(result['answer'])
            need(len(raw_answer) <= MAX_OBSERVED_ANSWER)
            seen = set()
            for item in raw_answer:
                seen.add(check_record(item))
            observations.append({'id': oid, 'query': ref_query,
                                 'profile': ref_profile, 'status': 'response',
                                 'rcode': rcode, 'answer': seen})
        else:
            raise Invalid()

    return zones, profiles, queries, observations


# --------------------------------------------------------------------------
# resolution model
# --------------------------------------------------------------------------

def select_zone(zones, name):
    for zone in zones:
        suffix = zone['suffix']
        if suffix is None or name == zone['origin'] or name.endswith(suffix):
            return zone
    return None


def closest_encloser(zone, name):
    node = parent_name(name)
    while node is not None:
        if node in zone['existing']:
            return node
        node = parent_name(node)
    return None


def select_source(zone, name, wildcard_mode):
    if name in zone['existing']:
        return name
    if wildcard_mode == 'off':
        return None
    encloser = closest_encloser(zone, name)
    if encloser is None:
        return None
    source = wildcard_name(encloser)
    if source not in zone['existing']:
        return None
    if wildcard_mode == 'one-label':
        need_labels = label_count(encloser) + 1
        if label_count(name) != need_labels:
            return None
    return source


def resolve(qname, qtype, profile, zones):
    max_aliases = profile['max_aliases']
    cname_mode = profile['cname']
    wildcard_mode = profile['wildcard']

    current = qname
    seen = set()
    followed = 0
    answer = []
    trace = []

    while True:
        # step 1
        trace.append(current)
        if current in seen:
            return ('SERVFAIL', 'LOOP', current, answer, trace)
        seen.add(current)

        # step 2
        zone = select_zone(zones, current)
        if zone is None:
            if followed == 0:
                return ('REFUSED', 'OUTSIDE', current, answer, trace)
            return ('NOERROR', 'EXTERNAL', current, answer, trace)

        # step 3
        source = select_source(zone, current, wildcard_mode)
        if source is None:
            return ('NXDOMAIN', 'NXDOMAIN', current, answer, trace)

        rrsets = zone['by_owner'].get(source, {})

        # step 4
        if qtype == 'CNAME':
            values = rrsets.get('CNAME')
            if values is None:
                return ('NOERROR', 'NODATA', current, answer, trace)
            for data in values:
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': data})
            return ('NOERROR', 'ANSWER', current, answer, trace)

        # step 5
        values = rrsets.get('CNAME')
        if values is not None:
            target = values[0]
            if cname_mode == 'stop':
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': target})
                return ('NOERROR', 'CNAME_STOP', current, answer, trace)
            if followed >= max_aliases:
                return ('SERVFAIL', 'LIMIT', current, answer, trace)
            answer.append({'owner': current, 'type': 'CNAME', 'data': target})
            followed += 1
            current = target
            continue

        # step 6
        values = rrsets.get(qtype)
        if values is None:
            return ('NOERROR', 'NODATA', current, answer, trace)
        for data in values:
            answer.append({'owner': current, 'type': qtype, 'data': data})
        return ('NOERROR', 'ANSWER', current, answer, trace)


def projection(rcode, answer_records):
    return (rcode, frozenset((rec['owner'], rec['type'], rec['data'])
                             for rec in answer_records))


# --------------------------------------------------------------------------
# diagnostic basis
# --------------------------------------------------------------------------

def partition_of(vectors):
    """Restricted-growth encoding of the partition induced by `vectors`."""
    labels = {}
    out = []
    for vector in vectors:
        label = labels.get(vector)
        if label is None:
            label = len(labels)
            labels[vector] = label
        out.append(label)
    return tuple(out)


def equivalence_classes(profile_ids, full_vectors):
    groups = {}
    for index, vector in enumerate(full_vectors):
        groups.setdefault(vector, []).append(profile_ids[index])
    classes = [sorted(group) for group in groups.values()]
    classes.sort()
    return classes


def minimum_basis(query_ids, costs, signatures, profile_count, target):
    """Exact minimum-cost, then minimum-count separating query subset.

    State space is the partition of profiles induced by the selected queries,
    which has at most Bell(profile_count) members, so the DP is tiny.
    """
    initial = (0,) * profile_count
    if initial == target:
        return [], 0, 0
    states = {initial: (0, 0, 0)}
    for index, qid in enumerate(query_ids):
        column = signatures[index]
        if column is None:
            continue
        weight = costs[index]
        bit = 1 << index
        updated = dict(states)
        for key, (cost, count, mask) in states.items():
            combined = partition_of(tuple(zip(key, column)))
            new_cost = cost + weight
            new_count = count + 1
            current = updated.get(combined)
            if current is None or (new_cost, new_count) < (current[0],
                                                           current[1]):
                updated[combined] = (new_cost, new_count, mask | bit)
        states = updated
    best = states.get(target)
    need(best is not None)
    mask = best[2]
    chosen = [query_ids[i] for i in range(len(query_ids)) if mask >> i & 1]
    chosen.sort()
    return chosen, best[0], best[1]


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def analyze(raw_bytes):
    zones, profiles, queries, observations = parse_document(raw_bytes)

    sorted_profile_ids = sorted(p['id'] for p in profiles)
    profiles_by_id = {p['id']: p for p in profiles}
    sorted_query_ids = sorted(q['id'] for q in queries)
    queries_by_id = {q['id']: q for q in queries}

    runs = []
    projections = {}
    for qid in sorted_query_ids:
        query = queries_by_id[qid]
        for pid in sorted_profile_ids:
            profile = profiles_by_id[pid]
            rcode, termination, final_name, answer, trace = resolve(
                query['name'], query['type'], profile, zones)
            runs.append({
                'query': qid,
                'profile': pid,
                'rcode': rcode,
                'termination': termination,
                'final_name': final_name,
                'answer': answer,
                'trace': trace,
            })
            projections[(qid, pid)] = projection(rcode, answer)

    audits = []
    for obs in sorted(observations, key=lambda o: o['id']):
        if obs['status'] == 'timeout':
            audits.append({'id': obs['id'], 'verdict': 'unobserved',
                           'different': []})
            continue
        expected_rcode, expected_set = projections[(obs['query'],
                                                    obs['profile'])]
        different = []
        if obs['rcode'] != expected_rcode:
            different.append('rcode')
        if obs['answer'] != expected_set:
            different.append('answer')
        if different:
            audits.append({'id': obs['id'], 'verdict': 'divergence',
                           'different': different})
        else:
            audits.append({'id': obs['id'], 'verdict': 'match',
                           'different': []})

    profile_count = len(sorted_profile_ids)
    columns = []
    full_vectors = [()] * profile_count
    full_vectors = [[] for _ in range(profile_count)]
    for qid in sorted_query_ids:
        column = tuple(projections[(qid, pid)] for pid in sorted_profile_ids)
        columns.append(column)
        for index in range(profile_count):
            full_vectors[index].append(column[index])
    full_vectors = [tuple(vector) for vector in full_vectors]

    classes = equivalence_classes(sorted_profile_ids, full_vectors)
    target = partition_of(full_vectors)
    costs = [queries_by_id[qid]['cost'] for qid in sorted_query_ids]
    basis, cost, count = minimum_basis(sorted_query_ids, costs, columns,
                                       profile_count, target)

    return {
        'runs': runs,
        'audits': audits,
        'diagnostic': {
            'equivalence': classes,
            'basis': basis,
            'cost': cost,
            'count': count,
        },
    }


def main():
    try:
        raw_bytes = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
    except Exception:
        raw_bytes = b''
    try:
        result = analyze(raw_bytes)
        payload = json.dumps(result, separators=(',', ':'),
                             ensure_ascii=False)
    except Exception:
        payload = ERROR_JSON
    sys.stdout.write(payload + '\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
