"""Independent reference implementation written directly from the spec text."""
import ipaddress, itertools

def canon_name(s):
    return s.lower()

def labels(name):
    if name == '.':
        return []
    return name[:-1].split('.')

def nlabels(name):
    return len(labels(name))

def parent(name):
    if name == '.':
        return None
    p = name[name.index('.')+1:]
    return p or '.'

def below(name, origin):
    if origin == '.':
        return True
    ls, lo = labels(name), labels(origin)
    return ls[len(ls)-len(lo):] == lo

class Zone:
    def __init__(self, origin, records):
        self.origin = canon_name(origin)
        self.exists = {self.origin}
        self.data = {}   # owner -> type -> set(data)
        for owner, t, d in records:
            owner = canon_name(owner)
            n = owner
            while True:
                self.exists.add(n)
                if n == self.origin:
                    break
                n = parent(n)
            self.data.setdefault(owner, {}).setdefault(t, set()).add(d)

    def rrset(self, name, t):
        return sorted(self.data.get(name, {}).get(t, ()))

    def source(self, name, wc):
        if name in self.exists:
            return name
        if wc == 'off':
            return None
        # closest encloser: longest existing strict ancestor
        cand = parent(name)
        enc = None
        while cand is not None:
            if cand in self.exists:
                enc = cand
                break
            cand = parent(cand)
        if enc is None:
            return None
        src = ('*.' + enc) if enc != '.' else '*.'
        if src not in self.exists:
            return None
        if wc == 'one-label' and nlabels(name) != nlabels(enc) + 1:
            return None
        return src

def pick_zone(zones, name):
    best = None
    for z in zones:
        if below(name, z.origin):
            if best is None or nlabels(z.origin) > nlabels(best.origin):
                best = z
    return best

def resolve(name, qtype, prof, zones):
    cur = canon_name(name)
    seen = set()
    followed = 0
    ans = []
    trace = []
    while True:
        trace.append(cur)
        if cur in seen:
            return ('SERVFAIL','LOOP',cur,ans,trace)
        seen.add(cur)
        z = pick_zone(zones, cur)
        if z is None:
            return ('REFUSED','OUTSIDE',cur,ans,trace) if followed == 0 else ('NOERROR','EXTERNAL',cur,ans,trace)
        src = z.source(cur, prof['wildcard'])
        if src is None:
            return ('NXDOMAIN','NXDOMAIN',cur,ans,trace)
        if qtype == 'CNAME':
            vals = z.rrset(src, 'CNAME')
            if vals:
                ans += [{'owner':cur,'type':'CNAME','data':v} for v in vals]
                return ('NOERROR','ANSWER',cur,ans,trace)
            return ('NOERROR','NODATA',cur,ans,trace)
        vals = z.rrset(src, 'CNAME')
        if vals:
            tgt = vals[0]
            if prof['cname'] == 'stop':
                ans.append({'owner':cur,'type':'CNAME','data':tgt})
                return ('NOERROR','CNAME_STOP',cur,ans,trace)
            if followed == prof['max_aliases']:
                return ('SERVFAIL','LIMIT',cur,ans,trace)
            ans.append({'owner':cur,'type':'CNAME','data':tgt})
            followed += 1
            cur = tgt
            continue
        vals = z.rrset(src, qtype)
        if vals:
            ans += [{'owner':cur,'type':qtype,'data':v} for v in vals]
            return ('NOERROR','ANSWER',cur,ans,trace)
        return ('NOERROR','NODATA',cur,ans,trace)

def sig(rcode, ans):
    return (rcode, frozenset((r['owner'],r['type'],r['data']) for r in ans))

def analyze(doc):
    zones = [Zone(z['origin'], [(r['owner'], r['type'], canon_data(r['type'], r['data'])) for r in z['records']]) for z in doc['zones']]
    profiles = doc['profiles']
    queries = doc['queries']
    pids = sorted(p['id'] for p in profiles)
    qids = sorted(q['id'] for q in queries)
    pmap = {p['id']:p for p in profiles}
    qmap = {q['id']:q for q in queries}
    runs = []
    sigs = {}
    for qid in qids:
        for pid in pids:
            q = qmap[qid]
            rc, term, fin, ans, tr = resolve(q['name'], q['type'], pmap[pid], zones)
            runs.append({'query':qid,'profile':pid,'rcode':rc,'termination':term,'final_name':fin,
                         'answer':ans,'trace':tr})
            sigs[(qid,pid)] = sig(rc, ans)
    audits = []
    for o in sorted(doc['observations'], key=lambda x: x['id']):
        r = o['result']
        if r['status'] == 'timeout':
            audits.append({'id':o['id'],'verdict':'unobserved','different':[]})
            continue
        obs = (r['rcode'], frozenset((canon_name(x['owner']), x['type'], canon_data(x['type'], x['data'])) for x in r['answer']))
        exp = sigs[(o['query'], o['profile'])]
        diff = []
        if obs[0] != exp[0]: diff.append('rcode')
        if obs[1] != exp[1]: diff.append('answer')
        audits.append({'id':o['id'],'verdict':'match' if not diff else 'divergence','different':diff})
    # equivalence
    groups = {}
    for pid in pids:
        groups.setdefault(tuple(sigs[(qid,pid)] for qid in qids), []).append(pid)
    classes = sorted(sorted(g) for g in groups.values())
    pairs = [(a,b) for a,b in itertools.combinations(pids,2) if any(sigs[(q,a)]!=sigs[(q,b)] for q in qids)]
    best = None
    n = len(qids)
    for r in range(n+1):
        for combo in itertools.combinations(range(n), r):
            ok_ = all(any(sigs[(qids[i],a)]!=sigs[(qids[i],b)] for i in combo) for a,b in pairs)
            if ok_:
                c = sum(qmap[qids[i]]['cost'] for i in combo)
                if best is None or (c, len(combo)) < best[0]:
                    best = ((c, len(combo)), sorted(qids[i] for i in combo))
        if best is not None:
            break
    if best is None:
        best = ((0,0), [])
    return {'runs':runs,'audits':audits,'diagnostic':{'equivalence':classes,'basis':best[1],'cost':best[0][0],'count':best[0][1]}}

def canon_data(t, v):
    if t == 'AAAA':
        return ipaddress.IPv6Address(v).compressed
    if t == 'CNAME':
        return canon_name(v)
    return v
